def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import math
    x = [float(v) for v in history if math.isfinite(float(v))]
    if horizon <= 0:
        return []
    if not x:
        return [0.0]*horizon

    def line(y, log_mode=False):
        z = [math.log(max(v,1e-9)) for v in y] if log_mode else y
        n = len(z)
        mt = (n-1)/2.0
        mz = sum(z)/n
        den = sum((i-mt)**2 for i in range(n))
        b = sum((i-mt)*(z[i]-mz) for i in range(n))/den if den else 0.0
        a = mz-b*mt
        return a,b

    def predict(y, kind, steps):
        n = len(y)
        if kind == 'level':
            return [y[-1]]*steps
        if kind == 'linear':
            a,b = line(y)
            return [a+b*(n+k) for k in range(steps)]
        a,b = line(y,True)
        b = min(0.0,max(-0.25,b))
        return [math.exp(a+b*(n+k)) for k in range(steps)]

    candidates = []
    for w in (12,20,32,48,64,96):
        if w <= len(x):
            for kind in ('level','linear','log'):
                candidates.append((kind,w))
    if not candidates:
        return [x[-1]]*horizon
    best = None
    max_back = min(32,len(x)//3)
    origins = list(range(4,max_back+1,4))
    for kind,w in candidates:
        loss = []
        for back in origins:
            end = len(x)-back
            if end < w:
                continue
            steps = min(8,back)
            preds = predict(x[end-w:end],kind,steps)
            for j,p in enumerate(preds):
                actual = x[end+j]
                loss.append(200.0*abs(p-actual)/(abs(p)+abs(actual)+1e-9))
        score = sum(loss)/len(loss) if loss else float('inf')
        if best is None or score < best[0]:
            best = (score,kind,w)
    _,kind,w = best
    out = predict(x[-w:],kind,horizon)
    if min(x[-w:]) >= 0.0:
        out = [max(0.0,v) for v in out]
    return [float(v if math.isfinite(v) else x[-1]) for v in out]
